function Journey() {
  const rm = useReducedMotion();
  const cardRefs = useRef([]);
  const [narrow, setNarrow] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(max-width:700px)");
    const on = (e) => setNarrow(e.matches);
    on(mq);
    mq.addEventListener ? mq.addEventListener("change", on) : mq.addListener(on);
    return () => { mq.removeEventListener ? mq.removeEventListener("change", on) : mq.removeListener(on); };
  }, []);

  const base = narrow ? 76 : 96;
  const gap = narrow ? 12 : 18;

  useEffect(() => {
    if (rm) return;
    const cards = cardRefs.current.filter(Boolean);
    if (!cards.length) return;
    const settleSpan = narrow ? 110 : 170;
    let raf = 0, ticking = false;

    const apply = () => {
      ticking = false;
      for (let i = 0; i < cards.length - 1; i++) {
        const next = cards[i + 1];
        if (!next) continue;
        const nextStickyTop = base + (i + 1) * gap;
        const dist = next.getBoundingClientRect().top - nextStickyTop;
        const progress = Math.min(1, Math.max(0, 1 - dist / settleSpan));
        cards[i].style.transform = progress > 0
          ? "translateY(" + (progress * -10).toFixed(2) + "px) scale(" + (1 - progress * 0.045).toFixed(3) + ")"
          : "none";
        cards[i].style.filter = progress > 0 ? "brightness(" + (1 - progress * 0.22).toFixed(3) + ")" : "none";
      }
    };
    const onScroll = () => { if (!ticking) { ticking = true; raf = requestAnimationFrame(apply); } };
    apply();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      cancelAnimationFrame(raf);
      cards.forEach((c) => { if (c) { c.style.transform = ""; c.style.filter = ""; } });
    };
  }, [rm, narrow, base, gap]);

  return (
    <Section id="journey" idx="03" name="Journey">
      <Split as="h2" text="How the last three years actually went." />
      <div className="jstack">
        {JOURNEY.map((j, i) => (
          <article
            className="jcard"
            key={j.title}
            ref={(el) => (cardRefs.current[i] = el)}
            style={{ top: (base + i * gap) + "px", zIndex: i + 1 }}
          >
            <div className="jcard-top">
              <span className="jcard-num">{"0" + (i + 1)}</span>
              <span className="jcard-when">{j.when}</span>
            </div>
            <h3>{j.title}</h3>
            <p>{j.body}</p>
          </article>
        ))}
      </div>
    </Section>
  );
}

function Counter({ to }) {
  const [ref, seen] = useInView({ threshold: 0.5 });
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!seen) return;
    let raf = 0, start = 0;
    const step = (ts) => {
      if (!start) start = ts;
      const p = Math.min((ts - start) / 950, 1);
      setN(Math.round(to * (1 - Math.pow(1 - p, 3))));
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [seen, to]);
  return <b ref={ref}>{n}</b>;
}

